
-- DROP TABLE IF EXISTS mortgage_repayment;
CREATE TABLE `mortgage_repayment`
(
    `id`                    bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID' PRIMARY KEY,
    `user_id`               bigint COMMENT '所属用户ID',
    `user_nick_name`        varchar(64) COMMENT '所属用户昵称',
    `loan_type`             tinyint        NOT NULL COMMENT '贷款类型：1-公积金贷款 2-商业贷款 3-组合贷款',
    `repayment_period`      int                     DEFAULT NULL COMMENT '还款期数',
    `actual_repayment_date` int            NOT NULL COMMENT '实际还款日期',
    `actual_principal`      decimal(15, 2) NOT NULL COMMENT '实际还款本金',
    `actual_interest`       decimal(15, 2) NOT NULL COMMENT '实际还款利息',
    `actual_overdue_fee`    decimal(15, 2)          DEFAULT '0.00' COMMENT '实际支付的逾期费用',
    `actual_total`          decimal(15, 2) GENERATED ALWAYS AS (((`actual_principal` + `actual_interest`) + `actual_overdue_fee`)) STORED COMMENT '实际还款总金额（自动计算）',
    `remaining_loan_amount` decimal(18, 2)          DEFAULT NULL COMMENT '还款后当前剩余贷款本金金额',
    `payment_method`        varchar(20)    NOT NULL COMMENT '还款方式：银行卡、支付宝、微信等',
    `payment_no`            varchar(50)             DEFAULT NULL COMMENT '支付单号/银行流水号',
    `actual_LPR`            decimal(4, 2)           DEFAULT NULL COMMENT '当前实际使用的贷款利率百分比，如：3.5%',
    `actual_BP`             decimal(5, 1)           DEFAULT NULL COMMENT '当前实际使用的基点，如：-30‱',
    `realtime_LPR`          decimal(4, 2)           DEFAULT NULL COMMENT '当前实时的贷款利率百分比，如：3.5%',
    `realtime_BP`           decimal(5, 1)           DEFAULT NULL COMMENT '当前实时的基点，如：-30‱',
    `remark`                varchar(500)            DEFAULT NULL COMMENT '备注（如：提前还款、组合贷公积金部分等）',
    `created`               datetime       NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
    `updated`               datetime       NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '记录更新时间'
) ENGINE=InnoDB COMMENT='房贷实际还款记录表（区分公积金/商业）';


